//! The qualifier's two rules for action evaluation (spec §11 GR-13, GR-35),
//! beside `actions.rs` rather than in it (that file is near the cap), as
//! GR-12's `actions_curves.rs` is.
//!
//! §5.4 interpolates numbers, so an animated hue centre from 350 to 10
//! would sweep the long way round, through the greens and blues at 180.
//! The owner chose the SHORT way round (G2-4's choice 11): before the lerp,
//! [`align_hue_center`] moves the interpolation TARGET's centre by ±360 when
//! the two centres are more than 180 degrees apart, so the lerp takes the
//! shorter arc (350 → 370), and `actions_clamp_grade.rs`'s `clamp_qualifier`
//! brings the lerped centre back onto the circle with `rem_euclid 360`
//! (355, then 0, then 5). Two centres exactly 180 apart have no shorter
//! arc and go linearly. Only the target of the action the time is INSIDE
//! is touched: an ended action's end is merged as written.
//!
//! [`qualifier_json`] writes a qualifier with its `blur` always present
//! (GR-35), where the file leaves a 0 out: §5.4's lerp walks only its FROM
//! side's keys, so a blur absent there would not animate from 0 and would
//! jump at the end. `actions.rs`'s `video_json` writes a non-neutral
//! qualifier through it; a neutral one stays absent, so a qualifier turned
//! on still switches at the end, as a range does.

use serde_json::Value;

use crate::actions::to_json;
use crate::model::Qualifier;

/// `qualifier` as JSON with `"blur"` always present, even at 0 (module doc).
pub(crate) fn qualifier_json(qualifier: &Qualifier) -> Value {
    let mut value = to_json(qualifier);
    if let Value::Object(fields) = &mut value {
        fields.insert("blur".to_string(), to_json(&qualifier.blur));
    }
    value
}

/// The `video.qualifier.hue.center` number of an action state, mutably.
fn center(state: &mut Value) -> Option<&mut Value> {
    state
        .get_mut("video")?
        .get_mut("qualifier")?
        .get_mut("hue")?
        .get_mut("center")
}

/// On the two states' `video.qualifier.hue.center`, when both are numbers
/// and more than 180 apart: `to`'s centre moves by ±360 so the two are less
/// than 180 apart (module doc). Anything else is left alone.
pub(crate) fn align_hue_center(from: &mut Value, to: &mut Value) {
    let Some(start) = center(from).and_then(|value| value.as_f64()) else {
        return;
    };
    let Some(end) = center(to) else {
        return;
    };
    let Some(target) = end.as_f64() else {
        return;
    };
    let turn = crate::model::HUE_TURN;
    let moved = if target - start > turn / 2.0 {
        target - turn
    } else if start - target > turn / 2.0 {
        target + turn
    } else {
        return;
    };
    if let Some(number) = serde_json::Number::from_f64(moved) {
        *end = Value::Number(number);
    }
}
//! The curves' JSON helpers for action evaluation (spec §11 GR-12, GR-34),
//! beside `actions.rs` rather than in it (that file is near the cap).
//!
//! [`curves_json`] writes all six channels, an absent one as its domain's
//! identity ([`IDENTITY_CURVE`], `IDENTITY_HUE_SHIFT`, `IDENTITY_HUE_GAIN`,
//! spec §11 GR-32), for every reader of `actions::video_json`: the state an
//! action interpolates from, the patch template (so `curves.red` is a known
//! key) and `split`'s state. [`align_identity_curves`] is the one rule the
//! list rule needs to animate a grade from neutral: an identity channel
//! meeting a curve of a different count takes that curve's x's — on a tone
//! curve with y = x and its ends at `[0, 0]` and `[1, 1]`, on a hue curve
//! with the neutral value — so the two lists match and interpolate per
//! point.
//!
//! Any other count change — two non-identity curves of different point
//! counts — BLENDS their values (GR-34): the list rule holds the list at its
//! start value `a`, so the evaluated props hold `a`, and [`curve_blends`]
//! names each such channel with the end curve `b` and the eased progress t.
//! [`blended_curves_json`] writes the recipe's and `clip_state`'s `curves`
//! with each blended channel as `{from, to, t}`, which Swift's strip samples
//! as `(1 − t)·a(x) + t·b(x)`. The core never samples a spline; a blend is
//! never written to a file (the model, a split, a paste and the template
//! hold points through [`curves_json`]).

use serde_json::{Map, Value};

use crate::actions::to_json;
use crate::actions_clamp_grade::clamp_curves;
use crate::model::{CurveDomain, CurvePoint, Curves};

/// One channel blended inside an action (spec §11 GR-34): its held curve
/// `from`, the action's clamped end curve `to`, both non-identity and of
/// different point counts, and the eased progress `t`, strictly inside 0…1.
#[derive(Debug, Clone, PartialEq)]
pub struct CurveBlend {
    pub channel: &'static str,
    pub from: Vec<CurvePoint>,
    pub to: Vec<CurvePoint>,
    pub t: f64,
}

/// The channels to blend at eased progress `t`: one per channel, in model
/// order, where `held` (the evaluated, clamped curves) and the action's
/// merged `target` (its `video.curves` decoded and clamped as an end is) are
/// both non-identity with different point counts. Empty unless 0 < t < 1,
/// and when the target's curves do not decode.
pub(crate) fn curve_blends(held: &Curves, target: &Value, t: f64) -> Vec<CurveBlend> {
    if t.is_nan() || t <= 0.0 || t >= 1.0 {
        return Vec::new();
    }
    let Some(value) = target.get("video").and_then(|video| video.get("curves")) else {
        return Vec::new();
    };
    let Ok(mut ends) = serde_json::from_value::<Curves>(value.clone()) else {
        return Vec::new();
    };
    clamp_curves(&mut ends);
    let mut out = Vec::new();
    for ((channel, _, from), (_, _, to)) in held.named().into_iter().zip(ends.named()) {
        if let (Some(from), Some(to)) = (from, to) {
            if from.len() == to.len() {
                continue;
            }
            out.push(CurveBlend {
                channel,
                from: from.clone(),
                to: to.clone(),
                t,
            });
        }
    }
    out
}

/// [`curves_json`] with each blended channel written as `{"from": [[x, y],
/// …], "to": [[x, y], …], "t": t}` (spec §11 GR-34): the recipe's `curves`
/// and `clip_state`'s `video.curves`. With no blends it is [`curves_json`]
/// byte for byte.
pub(crate) fn blended_curves_json(curves: &Curves, blends: &[CurveBlend]) -> Value {
    let mut out = curves_json(curves);
    if let Value::Object(channels) = &mut out {
        for blend in blends {
            let mut fields = Map::new();
            fields.insert("from".to_string(), to_json(&blend.from));
            fields.insert("to".to_string(), to_json(&blend.to));
            fields.insert("t".to_string(), to_json(&blend.t));
            channels.insert(blend.channel.to_string(), Value::Object(fields));
        }
    }
    out
}

/// The curves with every channel present: an absent one as its domain's
/// identity.
pub(crate) fn curves_json(curves: &Curves) -> Value {
    let mut out = Map::new();
    for (name, domain, curve) in curves.named() {
        let value = match curve {
            Some(points) => to_json(points),
            None => to_json(&domain.identity()),
        };
        out.insert(name.to_string(), value);
    }
    Value::Object(out)
}

/// A channel's points, when the value reads as a list of `[x, y]`.
fn points(value: &Value) -> Option<Vec<CurvePoint>> {
    serde_json::from_value::<Vec<CurvePoint>>(value.clone()).ok()
}

/// The identity on `other`'s x's: on a tone curve its first point `[0, 0]`,
/// its last `[1, 1]`, every point between at y = x; on a hue curve every
/// point at the neutral value.
fn aligned(other: &[CurvePoint], domain: CurveDomain) -> Value {
    let last = other.len().saturating_sub(1);
    let out: Vec<CurvePoint> = other
        .iter()
        .enumerate()
        .map(|(index, point)| {
            if let Some(neutral) = domain.neutral() {
                [point[0], neutral]
            } else if index == 0 {
                [0.0, 0.0]
            } else if index == last {
                [1.0, 1.0]
            } else {
                [point[0], point[0]]
            }
        })
        .collect();
    to_json(&out)
}

/// On the two states' `video.curves`, each channel where one side is the
/// identity and the other a curve of a different point count: the identity
/// side is replaced by the identity on the other's x's ([`aligned`]). Any
/// value that does not read as points is left alone (the list rule then
/// holds it, and [`curve_blends`] blends two curves of different counts).
pub(crate) fn align_identity_curves(from: &mut Value, to: &mut Value) {
    let (Some(Value::Object(from)), Some(Value::Object(to))) = (
        from.get_mut("video").and_then(|v| v.get_mut("curves")),
        to.get_mut("video").and_then(|v| v.get_mut("curves")),
    ) else {
        return;
    };
    for (name, domain, _) in Curves::default().named() {
        let (Some(a), Some(b)) = (from.get(name), to.get(name)) else {
            continue;
        };
        let (Some(a), Some(b)) = (points(a), points(b)) else {
            continue;
        };
        if a.len() == b.len() || a.is_empty() || b.is_empty() {
            continue;
        }
        if domain.is_identity(&a) {
            from.insert(name.to_string(), aligned(&b, domain));
        } else if domain.is_identity(&b) {
            to.insert(name.to_string(), aligned(&a, domain));
        }
    }
}
//! Adjustment clips (spec §11 GR-6): a clip kind with no picture of its
//! own. While it lasts, its `video.color` (all thirteen keys), its wheels
//! (spec §11 GR-11), its curves (GR-12), its look, its point filters (sepia, noir, vignette,
//! invert) and its opacity — the STRENGTH —
//! apply to everything already drawn behind it in its container (to the
//! pixels its qualifier selects, GR-13), the canvas
//! background included, and never to a track in front. The compositor's
//! eighth pipeline does the grading by reading the target it draws into
//! (`Compositor+Adjustment.swift`); the core's part is the kind, the op,
//! the rules below and the recipe's `{"kind":"adjustment"}` source.
//!
//! What it refuses, and why each is a refusal rather than a clamp:
//!
//! - **A nest.** A nest is flattened into the clips inside it, and an
//!   adjustment clip in there would grade the PARENT's layers behind the
//!   nest clip as well as the nest's own, which is not what a nest means.
//!   `nest` refuses it ([`adjustment_cannot_nest`]); `validate` errors on one
//!   inside a nest ([`adjustment_nested`]), which is what a file and a paste
//!   into a scope meet, because a scoped edit is validated on the MERGED
//!   parent (`scope.rs`); and `add_adjustment_clip` has no meaning inside a
//!   scope (`scope.rs`'s `refused_inside`).
//! - **A transition.** Both halves of a dissolve are drawn into one
//!   destination as a weighted pair; a pass that grades the destination has
//!   no half to be. `add_transition`, `set_transition` and
//!   `set_transition_style` refuse ([`adjustment_transition`]), and so does
//!   the overlap rule for any pair that holds one
//!   ([`adjustment_overlap`], called from `transition.rs`'s
//!   `check_overlap_rule`, the one placement door) — so
//!   `set_gained_transitions` never mints a transition on one. Fade it with
//!   opacity instead.
//! - **Blur, sharpen, pixelate and a blend mode.** The neighbourhood
//!   filters sample the layer's own texture around a pixel, and there is
//!   none; a blend combines a layer's colour with the canvas, and an
//!   adjustment clip has no colour of its own. `set_video`, `paste` and
//!   `paste_attributes` meet [`check_adjustment_video`] beside `check_blend`
//!   (errors, its precedent), and an action's end carrying one is closed by
//!   the evaluator ([`clamp_adjustment`]), as `clamp_video` closes a nest's
//!   blend.
//!
//! **On a matte track it is inert** ([`Project::inert_adjustment`]): a
//! matte group is one track, and two clips on one track share an instant
//! only in a transition, which is refused, so the clip could only be the
//! group's sole member and would act as an EMPTY matte. The recipe leaves
//! it out before the mattes are answered. On a track CUT by a matte it
//! grades only inside the matte, which needs nothing here: the compositor
//! weights its pass by the coverage like any matted layer's.
//!
//! Its stored transform, crop, corner, shadow, reflection, chroma,
//! spotlight, obscure and motion placement are kept and do nothing;
//! refusing them would make Paste Attributes fail from any moved clip.
//!
//! **The qualifier is its alone** (spec §11 GR-13): `video.qualifier`
//! narrows which of the destination's pixels the pass grades, read before
//! the grade. On any other clip a non-neutral one is an error in its own
//! sentence ([`check_qualifier_clip`], beside `check_adjustment_video` in
//! `set_video`, `paste` and `paste_attributes`); one reached through a file
//! or an action's end on another clip is inert, because the recipe
//! publishes it only in an adjustment source (`recipe.rs`'s
//! `layer_source`). Paste Attributes drops it onto a picture clip, and an
//! adjustment target keeps its own when the payload clip is not an
//! adjustment clip (`edit_paste_attributes.rs`'s `copy_group`).

use crate::edit_described::Described;
use crate::model::{BlendMode, Clip, FilterKind, Project, Source, VideoProps};
use crate::nest::Instance;
use crate::outcome::Outcome;
use crate::time::Ticks;

impl Project {
    /// An adjustment clip at `at` on `track`, five seconds long unless
    /// `duration` says otherwise, at scale 1 with default `video` (spec §6,
    /// §11 GR-6). Placed through `add_described_clip`, so the overlap rule
    /// and its sentence are the same as any sourceless clip's — with the
    /// adjustment clause, since no overlap may hold one.
    pub fn add_adjustment_clip(
        &self,
        track: u32,
        at: Ticks,
        duration: Option<Ticks>,
    ) -> Result<Outcome, String> {
        self.add_described_clip(
            track,
            at,
            duration,
            Described {
                source: Source::Adjustment,
                scale: 1.0,
                text: None,
                shape: None,
                graphic: None,
            },
        )
    }

    /// Whether `instance` is an adjustment clip on a top-level matte track,
    /// which draws nothing and cuts nothing (this module's doc): the recipe
    /// drops it before `frame_mattes` sees it.
    pub(crate) fn inert_adjustment(&self, instance: &Instance) -> bool {
        is_adjustment(instance.clip)
            && instance.inside.is_empty()
            && !instance.track.matte.is_none()
    }
}

/// Whether the clip is an adjustment clip.
pub(crate) fn is_adjustment(clip: &Clip) -> bool {
    matches!(clip.source, Source::Adjustment)
}

/// The one rule about an adjustment CLIP's video group: no neighbourhood
/// filter and no blend mode. An `Err`, as `check_blend`'s is, so `paste` and
/// `paste_attributes` meet it through `settle_video` and refuse the whole
/// paste. Any other clip passes.
pub(crate) fn check_adjustment_video(clip: &Clip, props: &VideoProps) -> Result<(), String> {
    if !is_adjustment(clip) {
        return Ok(());
    }
    for filter in &props.filters {
        let name = match filter.kind {
            FilterKind::Blur => "blur",
            FilterKind::Sharpen => "sharpen",
            FilterKind::Pixelate => "pixelate",
            FilterKind::Sepia | FilterKind::Noir | FilterKind::Vignette | FilterKind::Invert => {
                continue
            }
        };
        return Err(format!(
            "clip {} is an adjustment clip and cannot take the {name} filter",
            clip.id
        ));
    }
    if props.blend != BlendMode::Normal {
        return Err(format!(
            "clip {} is an adjustment clip and cannot take a blend mode",
            clip.id
        ));
    }
    Ok(())
}

/// The one rule about a qualifier and its clip (spec §11 GR-13): only an
/// adjustment clip takes one. A neutral qualifier passes on any clip, so a
/// `null` patch is an identity everywhere. An `Err` (the error tier, as
/// [`check_adjustment_video`]'s), so `paste` and `paste_attributes` meet it
/// through `settle_video`.
pub(crate) fn check_qualifier_clip(clip: &Clip, props: &VideoProps) -> Result<(), String> {
    if is_adjustment(clip) || props.qualifier.is_neutral() {
        return Ok(());
    }
    Err(format!(
        "clip {} is not an adjustment clip and cannot take a qualifier",
        clip.id
    ))
}

/// The overlap rule's sentence for an overlapping pair that holds an
/// adjustment clip, naming the later one when both are; `None` when neither
/// is. Its one caller is `check_overlap_rule`, with a pair it has already
/// found overlapping.
pub(crate) fn adjustment_overlap(a: &Clip, b: &Clip) -> Option<String> {
    let named = if is_adjustment(b) {
        b
    } else if is_adjustment(a) {
        a
    } else {
        return None;
    };
    Some(format!(
        "clips {} and {} would overlap, and clip {} is an adjustment clip, which cannot take a \
         transition; fade it with opacity instead",
        a.id, b.id, named.id
    ))
}

/// The refusal `add_transition`, `set_transition` and
/// `set_transition_style` give an adjustment clip; `None` for any other.
pub(crate) fn adjustment_transition(clip: &Clip) -> Option<String> {
    is_adjustment(clip).then(|| {
        format!(
            "clip {} is an adjustment clip and cannot take a transition; fade it with opacity \
             instead",
            clip.id
        )
    })
}

/// `validate`'s error for an adjustment clip inside a nest; `whose` is
/// `check_clips`' container clause (`" in nest 4"`).
pub(crate) fn adjustment_nested(clip: u32, whose: &str) -> String {
    format!(
        "clip {clip}{whose} is an adjustment clip, and an adjustment clip cannot be inside a nest"
    )
}

/// `nest`'s refusal for a selection holding an adjustment clip.
pub(crate) fn adjustment_cannot_nest(clip: u32) -> String {
    format!("clip {clip} is an adjustment clip, and an adjustment clip cannot go inside a nest")
}

/// The evaluator's last line of defence for an adjustment clip (an
/// action's end is checked against the vocabulary, never the clip): a
/// blend forced to `normal` and the neighbourhood filters dropped.
pub(crate) fn clamp_adjustment(mut props: VideoProps) -> VideoProps {
    props.blend = BlendMode::Normal;
    props.filters.retain(|filter| {
        !matches!(
            filter.kind,
            FilterKind::Blur | FilterKind::Sharpen | FilterKind::Pixelate
        )
    });
    props
}
