/// One frame's luma waveform (spec §11 GR-5): for each of 256 column bins of
/// the picture, how many pixels sit at each of 256 levels of Rec. 709 luma Y′
/// on the encoded (sRGB) values. What View ▸ Scopes' Waveform draws and what
/// `render_frame {waveform}` writes beside its PNG — one type, so the panel and
/// the tool cannot count differently.
///
/// A pixel clips HIGH at level 255 (Y′ ≥ 254.5/255, what an 8-bit file writes
/// as 255) and LOW at level 0 (Y′ < 0.5/255); a column is marked when at least
/// `markShare` of its pixels clip.
struct WaveformTrace: Equatable {
    static let columns = 256
    static let levels = 256
    /// The share of a column's pixels that must clip for its mark: 0.5 %.
    static let markShare = 0.005

    /// `counts[column * levels + level]`.
    let counts: [UInt32]
    /// The analysed frame's size in pixels.
    let width: Int
    let height: Int
    /// What the frame holds (spec §11 HD-15): an HLG trace's Y′ is on BT.2020's
    /// weights and its JSON names its scale.
    var signal: ScopeSignal = .sdr

    /// Pixels at level 255, over every column.
    var clippedHigh: Int { clipped(level: Self.levels - 1) }
    /// Pixels at level 0, over every column.
    var clippedLow: Int { clipped(level: 0) }

    /// The whole frame's share clipping high, in percent.
    var highlightsPercent: Double { percent(clippedHigh) }
    /// The whole frame's share clipping low, in percent.
    var shadowsPercent: Double { percent(clippedLow) }

    /// "Highlights clipped 12.5 %" — the panel's first readout.
    var highlightsReadout: String { "Highlights clipped " + Self.spelled(highlightsPercent) }
    /// "Shadows clipped 0.0 %" — the panel's second readout.
    var shadowsReadout: String { "Shadows clipped " + Self.spelled(shadowsPercent) }

    /// The readouts before the first frame has been analysed.
    static let noHighlights = "Highlights clipped —"
    static let noShadows = "Shadows clipped —"

    /// A percentage as every readout spells it: one decimal, then " %".

    /// The column bins where at least `markShare` of the column's pixels clip
    /// high (`high`) or low.
    func marks(high: Bool) -> [Int] {
        let level = high ? Self.levels - 1 : 0
        return (0..<Self.columns).filter { column in
            let base = column * Self.levels
            let total = counts[base..<(base + Self.levels)].reduce(0) { $0 + Int($1) }
            return total > 0 && Double(counts[base + level]) >= Self.markShare * Double(total)
        }
    }

    /// What `render_frame {waveform}` writes: the counts as 256 arrays, one
    /// per column bin, each indexed by level, and every figure the panel shows;
    /// an HLG trace adds `signal` and `scale` (HD-15 (h)).
    func json() -> [String: Any] {
        let byColumn = (0..<Self.columns).map { column in
            counts[(column * Self.levels)..<((column + 1) * Self.levels)].map { Int($0) }
        }
        return signal.adding(to: [
            "columns": Self.columns, "levels": Self.levels, "width": width, "height": height,
            "counts": byColumn, "clipped_high": clippedHigh, "clipped_low": clippedLow,
            "marks_high": marks(high: true), "marks_low": marks(high: false),
            "highlights": highlightsPercent, "shadows": shadowsPercent,
        ], scaled: true)
    }

    private func clipped(level: Int) -> Int {
        (0..<Self.columns).reduce(0) { $0 + Int(counts[$1 * Self.levels + level]) }
    }

    private func percent(_ count: Int) -> Double {
        100 * Double(count) / Double(max(width * height, 1))
    }
}

/// The scopes' GPU passes (`Waveform.metal`: `framejob_waveform_bin`,
/// `framejob_parade_bin`, `framejob_vectorscope_bin`, `framejob_histogram_bin`;
/// spec §11 GR-5, GR-10): one thread per pixel, each kind into a counts
/// buffer of its own, under GR-10's counting rule.
///
/// Two callers. `WaveformTaps` encodes the shown passes into ONE command
/// buffer of its own over the compositor's finished destination (`encode`),
/// never waiting; `render_frame {waveform, parade, vectorscope, histogram}`
/// analyses the frame it just rendered and waits (`analyze(image:passes:)`),
/// off the main thread like the rest of that tool. A pass is a kind and, for
/// the vectorscope, its zoom (`ScopePass`, spec §11 GR-31); the kind-keyed
/// forms are the ×1 passes. Every iteration over a set of passes runs in
/// `ScopePass.ordered` order.
//! `paste_attributes` — Edit ▸ Paste Attributes and Edit ▸ Paste Graphic
//! Properties (spec §6, table "Clips"; spec §11 G-32).
//!
//! Its own module because it is the clipboard's OTHER use: `paste` makes a
//! payload fit and places it, and this copies properties onto clips that
//! are already there and places nothing. The two share one thing, the
//! payload, whose shape stays `edit_paste.rs`'s to know and is read through
//! its [`parse_payload`]. Cut out of `edit_paste.rs` under the size rule
//! (core/CLAUDE.md), as a pure move, ahead of G-32.
//!
//! `paste_attributes` copies the EARLIEST payload clip's property groups
//! onto clips already on the timeline. It is not in `edit_props.rs` because
//! the material comes from the clipboard, not from a caller's patch. A
//! group is REPLACED whole, never merged — "make this look like that" is
//! the gesture, and a merge would leave the target's shadow under a source
//! that had none. What a target keeps is what makes it the clip it is
//! rather than how it looks: a text clip's `content` and the `words` that
//! time it (spec §11 W-6 — a timing belongs to its words); a shape's
//! `kind`, `width`, `height`, `from` and `to`. Video and audio travel whole,
//! transform included — `audio.muted` and `keep_pitch` are properties like
//! opacity, and `keep_pitch` only acts when the speed is not 1, which does
//! not travel: `speed`, `enabled`, the actions, the transition, the name,
//! the label and the source are not properties at all.
//!
//! **The qualifier follows the clip kind** (spec §11 GR-13): only an
//! adjustment clip takes one, so a picture target gets none (dropped, which
//! `paste_attributes`' description says — D2-1: a paste's answer is not
//! the place for it), and an adjustment target keeps its own when the
//! payload clip is a picture clip, which has none to give. Between two
//! adjustment clips it is copied like any other video key.
//!
//! ### The fifth group
//!
//! `graphic` (G-32) copies a graphic clip's `props`, whole, onto clips
//! drawn by the SAME module, and the target keeps its `name`, `width`,
//! `height`, `in` and `length`. It is a group a caller NAMES and never one
//! of the default set: props hold a graphic's words as well as its look,
//! and ⌥⌘V has no picker. That is why the names are [`PasteGroup`] and not
//! `patch::Group`: a patch has no `graphic` group (G-10), and `Group` is
//! matched exhaustively wherever a patch is read.
//!
//! The copied map is checked for SHAPE only — `model_graphic.rs`'s
//! `check_props` with no schema, then `check_count` — and only when a
//! target takes it, the first time one does: a paste in which no target
//! takes `graphic` never reads the map, as the four groups are checked
//! only after they have landed on a target. The write is `insert` and
//! `shift_remove`, `model_graphic.rs`'s rule, so a key both sides have
//! keeps its slot. A target key the payload lacks that an action on the
//! target names (`actions_graphic.rs`'s `names_prop`) is KEPT in its slot,
//! so the action's ramp keeps its start (spec §11 G-34 (d), amending
//! G-32 (e)).

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};

use crate::actions_graphic::names_prop;
use crate::edit_adjustment::is_adjustment;
use crate::edit_paste::{absorb_media, parse_payload};
use crate::lut::{look_media_ids, remap_look_media};
use crate::model::{Clip, GraphicProps, Project, Qualifier, ShapeProps, Source, TextProps};
use crate::model_graphic::{check_count, check_props};
use crate::outcome::Outcome;
use crate::patch::{Group, GROUPS};
use crate::video_gate::{hide_silent_media, remap_hide_silent};

/// The five groups `paste_attributes` takes by name — `video | audio | text
/// | shape | graphic` on the wire. The first four are the PATCH groups
/// ([`Group`]); `graphic` is the paste's alone (module doc).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PasteGroup {
    Video,
    Audio,
    Text,
    Shape,
    Graphic,
}

impl PasteGroup {
    /// The wire name, which is the patch group's own for the first four.
    pub(crate) fn name(self) -> &'static str {
        match self.layer() {
            Some(layer) => layer.name(),
            None => "graphic",
        }
    }

    /// The patch group this names, or `None` for `graphic`, which is not a
    /// group of the layer.
    fn layer(self) -> Option<Group> {
        match self {
            PasteGroup::Video => Some(Group::Video),
            PasteGroup::Audio => Some(Group::Audio),
            PasteGroup::Text => Some(Group::Text),
            PasteGroup::Shape => Some(Group::Shape),
            PasteGroup::Graphic => None,
        }
    }

    /// The same group as a name a caller could have sent.
    fn of(layer: Group) -> PasteGroup {
        match layer {
            Group::Video => PasteGroup::Video,
            Group::Audio => PasteGroup::Audio,
            Group::Text => PasteGroup::Text,
            Group::Shape => PasteGroup::Shape,
        }
    }
}

/// Whether a clip HAS the group — the model's only notion of what a clip
/// can take, the same one `edit_props.rs`'s patches go by.
fn has_group(clip: &Clip, group: Group) -> bool {
    match group {
        Group::Video => clip.video.is_some(),
        Group::Audio => clip.audio.is_some(),
        Group::Text => clip.text.is_some(),
        Group::Shape => clip.shape.is_some(),
    }
}

/// What a graphic clip is drawn from, or `None` for a clip that is not one
/// — `set_graphic`'s test: the source AND the description.
fn graphic_of(clip: &Clip) -> Option<&GraphicProps> {
    match clip.source {
        Source::Graphic => clip.graphic.as_ref(),
        _ => None,
    }
}

/// Whether a clip has a group a caller can name.
fn has(clip: &Clip, group: PasteGroup) -> bool {
    match group.layer() {
        Some(layer) => has_group(clip, layer),
        None => graphic_of(clip).is_some(),
    }
}

/// The copied props as they may be stored: shape-checked with no schema,
/// `null`s dropped, counted (G-32 (f)). The sentences are
/// `model_graphic.rs`'s own.
fn checked_props(from: &GraphicProps) -> Result<Map<String, Value>, String> {
    let mut stored = check_props(&from.props, None)?;
    stored.retain(|_, value| !value.is_null());
    check_count(&stored)?;
    Ok(stored)
}

/// Makes `into` hold exactly `props` plus the keys in `keep`: a key that
/// neither `props` nor `keep` holds is removed with `shift_remove`, a key
/// both maps have keeps its slot, a kept key keeps its slot and value, and
/// a new key is appended in `props`' order.
fn replace_props(into: &mut Map<String, Value>, props: &Map<String, Value>, keep: &[String]) {
    let gone: Vec<String> = into
        .keys()
        .filter(|key| !props.contains_key(*key) && !keep.contains(*key))
        .cloned()
        .collect();
    for key in gone {
        into.shift_remove(&key);
    }
    for (key, value) in props {
        into.insert(key.clone(), value.clone());
    }
}

/// Replaces `target`'s group with a copy of `source`'s, keeping the fields
/// that make the target the clip it is (module doc). A side that lacks the
/// group leaves the target as it was — the caller has already refused that
/// case by name, so this is only the shape that cannot invent a group.
fn copy_group(target: &mut Clip, source: &Clip, group: Group) {
    match group {
        Group::Video => {
            let picture_target = !is_adjustment(target);
            let picture_source = !is_adjustment(source);
            if let (Some(into), Some(from)) = (target.video.as_mut(), &source.video) {
                let own = into.qualifier;
                *into = from.clone();
                // The qualifier follows the clip kind (module doc, GR-13).
                if picture_target {
                    into.qualifier = Qualifier::default();
                } else if picture_source {
                    into.qualifier = own;
                }
            }
        }
        Group::Audio => {
            if let (Some(into), Some(from)) = (target.audio.as_mut(), &source.audio) {
                *into = *from;
            }
        }
        Group::Text => {
            if let (Some(into), Some(from)) = (target.text.as_mut(), &source.text) {
                let content = std::mem::take(&mut into.content);
                let words = std::mem::take(&mut into.words);
                *into = TextProps {
                    content,
                    words,
                    ..from.clone()
                };
            }
        }
        Group::Shape => {
            if let (Some(into), Some(from)) = (target.shape.as_mut(), &source.shape) {
                *into = ShapeProps {
                    kind: into.kind,
                    width: into.width,
                    height: into.height,
                    from: into.from,
                    to: into.to,
                    ..from.clone()
                };
            }
        }
    }
}

impl Project {
    /// Copies one payload clip's property groups onto every named clip (spec
    /// §6) — Edit ▸ Paste Attributes. The clip is the EARLIEST, then the
    /// front-most (`track` is a depth, 0 = front), then the lower id: Copy
    /// writes a selection in storage — creation — order, not the timeline's,
    /// so the array's first is a clip the user cannot see. Which fields
    /// travel, which a target keeps and why a group is replaced rather than
    /// merged are the module doc's.
    ///
    /// `groups` absent means every one of the four LAYER groups both sides
    /// have, silently skipping the rest: video onto a text clip from a media
    /// clip copies the video, leaves the text alone and drops the audio,
    /// which has nowhere to go. `graphic` is never in that set, and
    /// `skip_missing` changes nothing there. A NAMED group is different —
    /// one the source lacks is an `Err` naming the group, one a target lacks
    /// is `Err("clip N has no audio properties")`, the patches' answer, and
    /// `graphic` onto a clip drawn by another module is an `Err` naming both
    /// modules — because a caller who asked for it would otherwise never
    /// learn it did not happen. With `skip_missing` a caller says it does
    /// not need to: a named group the source lacks is dropped and a target
    /// that cannot take one is skipped for it (G-32). An empty explicit
    /// list, an identity paste and an empty selection are all identities.
    /// The copied layer groups then pass the range checks a patch does, so a
    /// payload written by hand cannot smuggle in a value the inspector would
    /// refuse; copied graphic props pass the shape check, the first time a
    /// target takes them.
    pub fn paste_attributes(
        &self,
        clips: &[u32],
        payload: &Value,
        groups: Option<&[PasteGroup]>,
        skip_missing: bool,
    ) -> Result<Outcome, String> {
        let payload = parse_payload(payload)?;
        let earliest = |c: &&Clip| (c.start, c.track, c.id);
        let Some(source) = payload.clips.iter().min_by_key(earliest) else {
            return Err("paste payload has no clips".to_string());
        };
        let mut named: Option<Vec<PasteGroup>> = None;
        if let Some(asked) = groups {
            let mut kept = Vec::new();
            for group in asked {
                if has(source, *group) {
                    kept.push(*group);
                } else if !skip_missing {
                    return Err(format!("payload clip has no {} properties", group.name()));
                }
            }
            named = Some(kept);
        }
        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();

        let mut next = self.clone();
        // Read at most once, by the first target that takes it (G-32 (f)).
        let mut copied: Option<Map<String, Value>> = None;
        // The source with its looks pointing at THIS project's LUTs, made by
        // the first target that takes the video group (spec §11 GR-8): the
        // LUTs it names are absorbed by path, as `paste` absorbs media, and
        // an id the payload lacks becomes no look.
        let mut looked: Option<Clip> = None;
        for id in ids {
            let Some(mut target) = next.clip(id).cloned() else {
                continue;
            };
            let chosen: Vec<PasteGroup> = match &named {
                Some(named) => named.clone(),
                None => GROUPS
                    .into_iter()
                    .filter(|g| has_group(source, *g) && has_group(&target, *g))
                    .map(PasteGroup::of)
                    .collect(),
            };
            let takes_video = chosen.contains(&PasteGroup::Video) && target.video.is_some();
            if takes_video && looked.is_none() {
                let looks = [
                    look_media_ids(source),
                    hide_silent_media(source).into_iter().collect(),
                ];
                let map = absorb_media(&mut next, &payload, &[], &looks.concat())?;
                let mut copy = source.clone();
                remap_look_media(&mut copy, &map);
                remap_hide_silent(&mut copy, &map);
                looked = Some(copy);
            }
            let from = looked.as_ref().unwrap_or(source);
            for group in chosen {
                if !has(&target, group) {
                    if skip_missing {
                        continue;
                    }
                    return Err(format!("clip {id} has no {} properties", group.name()));
                }
                let Some(layer) = group.layer() else {
                    let keep: Vec<String> = target.graphic.as_ref().map_or_else(Vec::new, |g| {
                        let named = g.props.keys().filter(|key| names_prop(&target, key));
                        named.cloned().collect()
                    });
                    let (Some(from), Some(into)) = (graphic_of(from), target.graphic.as_mut())
                    else {
                        continue;
                    };
                    if into.name != from.name {
                        if skip_missing {
                            continue;
                        }
                        return Err(format!(
                            "clip {id} is drawn by \"{}\" and the payload clip by \"{}\"; \
                             graphic props are pasted only between clips of one module",
                            into.name, from.name
                        ));
                    }
                    if copied.is_none() {
                        copied = Some(checked_props(from)?);
                    }
                    if let Some(props) = &copied {
                        replace_props(&mut into.props, props, &keep);
                    }
                    continue;
                };
                copy_group(&mut target, from, layer);
                next.normalise_and_check_group(&mut target, layer)?;
            }
            if let Some(slot) = next.clip_mut(id) {
                *slot = target;
            }
        }
        self.finish(next)
    }
}
//! `.cube` LUTs as media and as looks (spec §11 GR-8): the rules a `lut`
//! media row and a `video.look {kind: "lut", media}` obey, written once for
//! every door that meets them.
//!
//! - **The row.** A LUT is media so it is referenced, relinked and
//!   consolidated like footage, but it has no picture of its own: its row
//!   carries no video, audio, alpha or duration ([`check_lut_fields`], which
//!   `edit_track.rs`'s `check_media_fields` calls for `add_media`, a
//!   relink's probe and a pasted media row), and it is never placed as a clip — `add_clip`,
//!   `insert_clip`, `overwrite_clip` and `add_background` answer
//!   [`lut_not_placeable`].
//! - **The look.** `media` is required with `lut` and goes with nothing
//!   else, and must name a `lut` media of the project
//!   ([`Project::check_look_media`], beside `check_adjustment_video` on the
//!   patch path and on every pasted group, and in `validate` for a file),
//!   through [`Project::check_lut_reference`], which `media_color.rs`'s
//!   `color.lut` shares. A
//!   patch naming a built-in kind and no `media` drops a stored one
//!   ([`normalise_look`]), so a built-in kind on a LUT clip replaces the LUT.
//! - **An action's end** is never checked against the media list
//!   (`set_action_end` checks shape only), so an end may name a LUT that is
//!   not there: the evaluator reads such a look as NO look
//!   ([`Project::evaluates_as_look`]), and `actions.rs` switches `media` at
//!   the end like a `kind`, so an id is never interpolated.
//! - **Removing a used LUT** ([`Project::remove_lut`]) refuses naming the
//!   clips whose base look it is and the media whose Camera Log it is (spec
//!   §11 GR-16, `media.color.lut`), or with `with_clips` clears those looks
//!   and conversions and keeps the clips and the media; ends are left alone
//!   (inert by the evaluator).
//! - **Paste** brings a LUT's row by path like any media; an id the payload
//!   does not carry becomes no look ([`remap_look_media`]) rather than
//!   another media's id.

use std::collections::HashMap;

use serde_json::Value;

use crate::export_overrides::spelled;
use crate::model::{Clip, Look, LookKind, Media, MediaKind, Project, VideoProps};
use crate::outcome::Outcome;

/// The refusal for `media` on a built-in kind.
fn media_goes_with_lut(kind: LookKind) -> String {
    format!("video.look.media goes with kind lut, not {}", spelled(kind))
}

/// What `add_clip` and the other placing ops answer for a LUT: it is a look,
/// and the sentence says how to apply one.
pub(crate) fn lut_not_placeable(media: u32) -> String {
    format!(
        "media {media} is a LUT: apply it as a look (set_video {{look: {{kind: \"lut\", \
         media: {media}}}}}), it is not placed as a clip"
    )
}

/// A `lut` row's own check: it has no picture or sound, so none of the
/// flags or a duration. Any other kind passes.
pub(crate) fn check_lut_fields(media: &Media) -> Result<(), String> {
    if media.kind == MediaKind::Lut
        && (media.has_video || media.has_audio || media.has_alpha || media.duration != 0)
    {
        return Err("a lut media has no video, audio, alpha or duration".to_string());
    }
    Ok(())
}

/// After a video patch has merged: a patch that names a built-in `kind` and
/// no `media` drops a stored `media` (the built-in replaces the LUT), and a
/// patch that names `media` on a built-in kind is refused.
pub(crate) fn normalise_look(props: &mut VideoProps, patch: &Value) -> Result<(), String> {
    let Some(Value::Object(asked)) = patch.get("look") else {
        return Ok(());
    };
    let Some(look) = props.look.as_mut() else {
        return Ok(());
    };
    if look.kind == LookKind::Lut {
        return Ok(());
    }
    let names_media = asked.get("media").is_some_and(|media| !media.is_null());

import AppKit

/// One inspector row (spec §11 CI-9): the horizontal stack `inspectorRow`
/// always built — the mark gutter FIRST, with no spacing after it (CI-7) —
/// which now tracks the pointer over itself and answers a context menu.
///
/// The pointer is over the ROW, so the row tells its gutter (`hovered`); the
/// gutter decides whether that makes its ◆ a ×. The menu never reads the
/// hover: a window that is not key tracks none, and a right-click there must
/// offer the same items.
///
/// A field's or a popup's own right-click keeps its own menu, because neither
/// forwards it; the gutter, the label, a slider, a checkbox, the tags and the
/// trailing spacer reach this one.
final class InspectorRowView: NSStackView {
    let gutter: InspectorMarkGutter

    init(views: [NSView], gutter: InspectorMarkGutter) {
        self.gutter = gutter
        super.init(frame: .zero)
        for view in views { addArrangedSubview(view) }
        orientation = .horizontal
        alignment = .centerY
        spacing = 6
        setCustomSpacing(0, after: gutter)
        // As tall as the row and no taller: a fixed height would grow a row
        // of bare text (the "No filters" lines) and move everything under it.
        gutter.heightAnchor.constraint(equalTo: heightAnchor).isActive = true
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorRowView does not support NSCoder")
    }

    // MARK: Hover

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // Only this view's own areas: a tooltip is a tracking area too.
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        addTrackingArea(
            NSTrackingArea(
                rect: .zero, options: [.mouseEnteredAndExited, .activeInKeyWindow, .inVisibleRect],
                owner: self, userInfo: nil))
    }

    override func mouseEntered(with event: NSEvent) { setHovered(true) }
    override func mouseExited(with event: NSEvent) { setHovered(false) }

    func setHovered(_ hovered: Bool) {
        gutter.hovered = hovered
    }

    // MARK: The menu

    override func menu(for event: NSEvent) -> NSMenu? {
        contextMenu()
    }

    /// The row's items, in order: "Remove from action N" on a keyed row, "Go
    /// to action M" on a ◇ row, then — for a row with a default — "Set end
    /// value to default" with an action selected on a row that animates, else
    /// "Reset to default", disabled while the row already holds it. Nil when
    /// there would be no item.
    func contextMenu() -> NSMenu? {
        let menu = NSMenu()
        menu.autoenablesItems = false
        let binding = gutter.binding
        if gutter.isKeyed, let number = binding?.selectedActionNumber {
            add("Remove from action \(number)", #selector(removeFromAction(_:)), to: menu)
        }
        if case .other(let number) = gutter.mark {
            add("Go to action \(number)", #selector(goToAction(_:)), to: menu)
        }
        if let rowDefault = gutter.default {
            let atEnd = binding?.selectedAction != nil && gutter.animates
            let item = add(
                atEnd ? "Set end value to default" : "Reset to default",
                #selector(resetToDefault(_:)), to: menu)
            item.isEnabled = rowDefault.differs()
        }
        return menu.items.isEmpty ? nil : menu
    }

    @discardableResult
    private func add(_ title: String, _ action: Selector, to menu: NSMenu) -> NSMenuItem {
        let item = NSMenuItem(title: title, action: action, keyEquivalent: "")
        item.target = self
        menu.addItem(item)
        return item
    }

    @objc func removeFromAction(_ sender: Any?) {
        gutter.removeFromAction()
    }

    /// Selects the action the ◇ names, through the lane's own intent.
    @objc func goToAction(_ sender: Any?) {
        guard case .other(let number) = gutter.mark, let binding = gutter.binding,
              let id = binding.actionID(number: number)
        else { return }
        binding.selectAction(id)
    }

    @objc func resetToDefault(_ sender: Any?) {
        guard let rowDefault = gutter.default, let binding = gutter.binding else { return }
        binding.apply(rowDefault.name, rowDefault.ops())
    }
}
import AppKit

/// The section header: disclosure triangle, title in the micro-label face, the
/// current-state summary, and the Reset or Clear button pinned to the trailing
/// edge. The buttons are subviews so they eat their own clicks — everything
/// else toggles the group.
///
/// Spec §11 CI-9: a section EDITING an action (`marks.editing`) shows Clear,
/// only while the action keys one of its rows; otherwise it shows Reset, only
/// while it differs from its default. Both share the one slot, and at most
/// one is visible.
final class InspectorSectionHeader: NSView {
    var onToggle: (() -> Void)?
    var isExpanded = true {
        didSet { needsDisplay = true }
    }
    private var title = ""
    /// The last summary and marks drawn, so a refresh only redraws when one
    /// CHANGED — the panel refreshes on every document change and on every
    /// playhead move inside an action.
    private var lastSummary: String?
    private var marks = SectionMarks.empty
    /// Held so the summary can stop short of the VISIBLE one: they share the
    /// header's trailing end, and a summary drawn under a button would be
    /// unreadable. Clear is always built; Reset only for a section with one.
    private weak var resetButton: NSView?
    private weak var clearButton: NSView?
    /// The hover (#102, spec §11 CI-15 as amended): a second `DS.hoverFill`
    /// over the rest band, faded by its alpha, since a band drawn in
    /// `draw(_:)` cannot fade. The first subview, so Reset and Clear sit
    /// above it; it stops above the rule.
    let hoverBand = InspectorHeaderHoverBand()
    private(set) var isHovered = false

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
        hoverBand.translatesAutoresizingMaskIntoConstraints = false
        addSubview(hoverBand)
        NSLayoutConstraint.activate([
            hoverBand.leadingAnchor.constraint(equalTo: leadingAnchor),
            hoverBand.trailingAnchor.constraint(equalTo: trailingAnchor),
            hoverBand.topAnchor.constraint(equalTo: topAnchor),
            hoverBand.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -1),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorSectionHeader does not support NSCoder")
    }

    convenience init() {
        self.init(frame: .zero)
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: InspectorMetrics.headerHeight)
    }

    func configure(title: String, reset: (() -> Void)?, clear: @escaping () -> Void) {
        self.title = title
        clearButton = install(
            OptionButtonControl(title: "Clear", action: clear, enabled: { true }, onEdit: {}))
        if let reset {
            let button = install(
                OptionButtonControl(title: "Reset", action: reset, enabled: { true }, onEdit: {}))
            button.toolTip = "Reset this section to its defaults"
            resetButton = button
        }
        showButtons()
    }

    private func install(_ button: NSView) -> NSView {
        button.translatesAutoresizingMaskIntoConstraints = false
        addSubview(button)
        NSLayoutConstraint.activate([
            button.trailingAnchor.constraint(
                equalTo: trailingAnchor, constant: -InspectorMetrics.inset),
            button.centerYAnchor.constraint(equalTo: centerYAnchor),
        ])
        return button
    }

    /// CI-9's one slot: Clear while editing an action that keys the section,
    /// Reset while not editing and the section differs, else nothing.
    private func showButtons() {
        let editing = marks.editing
        clearButton?.isHidden = editing == nil || marks.keyed == 0
        clearButton?.toolTip = editing.map { "Remove this section from action \($0)" }
        resetButton?.isHidden = editing != nil || !marks.differs
    }

    /// The visible button's title — "Clear", "Reset" or nil.
    var buttonTitle: String? {
        if clearButton?.isHidden == false { return "Clear" }
        if resetButton?.isHidden == false { return "Reset" }
        return nil
    }

    /// The summary's ink: the action's when keyed, the body tier
    /// (`DS.textMuted`, spec §11 CI-9) when the section differs from its
    /// default, else faint.
    var summaryInk: NSColor {
        marks.keyed > 0 ? DS.action : marks.differs ? DS.textMuted : DS.textFaint
    }

    /// Takes the summary and the marks; redraws only when either moved.
    func refresh(summary: String?, marks: SectionMarks) {
        guard summary != lastSummary || marks != self.marks else { return }
        lastSummary = summary
        self.marks = marks
        showButtons()
        needsDisplay = true
    }

    override func mouseDown(with event: NSEvent) {
        onToggle?()
    }

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // Owner-filtered: a tooltip is a tracking area too (app/CLAUDE.md).
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        addTrackingArea(
            NSTrackingArea(
                rect: bounds, options: [.mouseEnteredAndExited, .activeInKeyWindow],
                owner: self, userInfo: nil))
    }

    /// Opens the section and writes NO preference — the selected action's
    /// auto-open (spec §11 CI-8), which must leave the person's own layout
    /// standing for when the action is left.
    func reveal() {
        isExpanded = true
        content.isHidden = false
        header.isExpanded = true
    }

    /// Opens the section as a DEFAULT, for a pane that decided after building
    /// it that this is the group to open (`ClipPane`'s "the first section is
    /// open when there is no Transform"). `defaultExpanded` cannot say it: the
    /// pane only knows which section is first once it has them all.
    ///
    /// **It defers to the user and writes nothing.** A section the user has
    /// ever toggled has a stored value, and re-opening a group somebody closed
    /// on every rebuild would be worse than the closed panel this fixes;
    /// storing the state here would then make that override permanent.
    /// Returns whether it opened the section, so a caller walking a list can
    /// stop at the first one that had no stored preference.
    @discardableResult
    func expandByDefault() -> Bool {
        guard UserDefaults.standard.object(forKey: Self.collapsedKeyPrefix + id) == nil,
              !isExpanded
        else { return false }
        isExpanded = true
        content.isHidden = false
        header.isExpanded = true
        return true
    }

    func refresh() {
        refreshOptionControls(in: content)
        foldMarks()
    }

    /// The header's Clear (spec §11 CI-9): every key the section's rows
    /// write that the selected action holds, out of its end patch in ONE
    /// `set_action_end`.
    func clear() {
        let gutters = Self.gutters(in: content)
        guard let binding = gutters.lazy.compactMap({ $0.binding }).first else { return }
        let keys = gutters.reduce(into: Set<String>()) { $0.formUnion($1.keyedWrites()) }
        binding.apply("Clear", binding.clearOps(keys))
    }

    /// The rows' gutters, in the order `refreshOptionControls(in:)` walks.
    private static func gutters(in view: NSView) -> [InspectorMarkGutter] {
        view.subviews.flatMap { subview -> [InspectorMarkGutter] in
            if let gutter = subview as? InspectorMarkGutter { return [gutter] }
            return gutters(in: subview)
        }
    }

    /// `marks` from the gutters as they stand, then the two things drawn from
    /// it: the ⊘ note and the header. A section is EDITING the selected
    /// action when any of its rows animates; one that none does (Document,
    /// Shape, a ⊘-only section) keeps its Reset, since its edits go to the
    /// clip.
    private func foldMarks() {
        let gutters = Self.gutters(in: content)
        let writing = gutters.filter { !$0.writes.isEmpty }
        let binding = gutters.lazy.compactMap { $0.binding }.first
        marks = SectionMarks(
            keyed: gutters.reduce(into: Set<String>()) { $0.formUnion($1.keyedWrites()) }.count,
            other: gutters.contains {
                if case .other = $0.mark { return true } else { return false }
            },
            allNotAnimatable: !writing.isEmpty
                && writing.allSatisfy { $0.mark == .notAnimatable },
            differs: differs?() ?? gutters.contains { $0.default?.differs() == true },
            editing: gutters.contains { $0.animates } ? binding?.selectedActionNumber : nil)
        inertNote?.refresh()
        header.refresh(summary: summary?(), marks: marks)
    }
}

/// The auto-open (spec §11 CI-8): the sections the selected action keys are
/// revealed on the sub-tab showing them, remembered for as long as that
import AppKit

/// The Color sub-tab's **Qualifier** section (spec §11 GR-13, grading-2
/// G2-4), on adjustment clips only, after Adjustment: which of the pixels
/// behind the clip its grade reaches.
///
/// Per range two rows — its checkbox (Hue, Saturation, Luma) in the label
/// column then its strip (`RangeStripControl`), then three captioned fields
/// (Centre, Width, Soft in whole degrees; Low, High, Soft to two decimals) —
/// then Invert, then Blur (spec §11 GR-35: the house slider and field,
/// 0–100 %, one step "Qualifier Blur"), then Pick from Canvas and the Show
/// Selection switch, both sent to the editor as commands
/// (`EditorViewController+Qualifier.swift`, `+Seeing`). A checkbox writes
/// `{}` or `null` (one step named after the range); a strip drag is the live trio; a field one commit; each sends the
/// WHOLE range to every selected clip, the first clip's values being the
/// ones shown (the mixed badge says when the others differ). Every row
/// writes `video.qualifier`, so a keyed action marks them all as one key.
extension VideoPane {
    // MARK: Qualifier

    func qualifierSection() -> InspectorSection {
        let binding = self.binding
        func qualifier() -> ColorQualifier { binding.videoProps.qualifier }
        func ops(_ patch: ColorQualifierPatch) -> [ReelOp] {
            binding.ops(video: VideoPatch(qualifier: patch))
        }
        var rows: [NSView] = []
        for range in QualifierRange.allCases {
            rows += qualifierRows(range, read: qualifier, ops: ops)
        }
        rows.append(
            inspectorCheckRow(
                "Invert", binding, name: "Qualifier",
                read: { qualifier().invert },
                ops: { ops(ColorQualifierPatch(invert: $0)) },
                mixed: { binding.mixedVideo { $0.qualifier.invert } }))
        rows.append(
            inspectorValueRow(
                "Blur", binding, name: "Qualifier Blur", unit: "%", decimals: 0, min: 0,
                max: 100, quick: [0, 25, 50, 75, 100],
                read: { qualifier().blur * 100 },
                ops: { ops(ColorQualifierPatch(blur: $0 / 100)) },
                mixed: { binding.mixedVideo { $0.qualifier.blur } }))
        let pick = commandButton(
            "Pick from Canvas", #selector(EditorViewController.pickQualifier(_:)),
            toolTip: "Click the preview to centre the ranges on a colour (Esc cancels)")
        let show = OptionCheckboxControl(
            label: "Show Selection",
            read: { [weak self] in
                guard let key = self?.inspector?.document?.recipeKey else { return false }
                return RecipeSource.shared.options(for: key).selection != nil
            },
            write: { [weak self] _ in
                self?.inspector?.onCommand?(
                    #selector(EditorViewController.toggleShowSelection(_:)))
            },
            enabled: { true }, onEdit: {})
        rows.append(inspectorButtonRow([pick, show]))
        return InspectorSection(
            id: "video.qualifier", title: "Qualifier",
            summary: { qualifier().summary },
            reset: { binding.apply("Qualifier", ops(.reset)) },
            differs: { !qualifier().isNeutral },
            defaultExpanded: false,
            rows: rows)
    }

    /// One range's two rows: the checkbox and the strip, then the fields.
    private func qualifierRows(
        _ range: QualifierRange, read: @escaping () -> ColorQualifier,
        ops: @escaping (ColorQualifierPatch) -> [ReelOp]
    ) -> [NSView] {
        let binding = self.binding
        let name = range.title
        func on() -> Bool { read().isOn(range) }
        let check = OptionCheckboxControl(
            label: name, read: on,
            write: { [weak binding] value in
                binding?.apply(name, ops(.toggle(range, value)))
            },
            enabled: { true },
            onEdit: { [weak binding] in binding?.edited() })
        check.translatesAutoresizingMaskIntoConstraints = false
        check.widthAnchor.constraint(equalToConstant: InspectorMetrics.labelWidth).isActive = true
        let strip = RangeStripControl(
            kind: range, read: read,
            begin: { [weak binding] in binding?.liveBegin() },
            update: { [weak binding] patch in binding?.liveUpdate(ops(patch)) },
            end: { [weak binding] in binding?.liveEnd(name) })
        let mixed: () -> Bool
        switch range {
        case .hue: mixed = { binding.mixedVideo { $0.qualifier.hue } }
        case .saturation: mixed = { binding.mixedVideo { $0.qualifier.saturation } }
        case .luma: mixed = { binding.mixedVideo { $0.qualifier.luma } }
        }
        let stripRow = inspectorRow(
            nil, [check, strip], mixed: mixed, binding: binding, writes: ops(.reset),
            default: InspectorRowDefault(
                name: name, differs: on, ops: { ops(.toggle(range, false)) }))
        let gutter = stripRow.gutter
        strip.keyed = { [weak gutter] in gutter?.isKeyed == true }
        return [stripRow, qualifierFields(range, read: read, ops: ops)]
    }

    /// The range's three captioned fields across one row.
    private func qualifierFields(
        _ range: QualifierRange, read: @escaping () -> ColorQualifier,
        ops: @escaping (ColorQualifierPatch) -> [ReelOp]
    ) -> NSView {
        let binding = self.binding
        let name = range.title
        func on() -> Bool { read().isOn(range) }
        typealias Field = (caption: String, max: Double, get: (ColorQualifier) -> Double,
                           put: (ColorQualifier, Double) -> ColorQualifierPatch)
        let fields: [Field]
        if range == .hue {
            func hue(_ q: ColorQualifier) -> QualifierHue { q.hue ?? .initial }
            fields = [
                ("Centre", 360, { hue($0).center },
                 { q, v in var h = hue(q); h.center = v; return ColorQualifierPatch(hue: .set(h)) }),
                ("Width", 360, { hue($0).width },
                 { q, v in var h = hue(q); h.width = v; return ColorQualifierPatch(hue: .set(h)) }),
                ("Soft", 180, { hue($0).softness },
                 { q, v in var h = hue(q); h.softness = v; return ColorQualifierPatch(hue: .set(h)) }),
            ]
        } else {
            func levels(_ q: ColorQualifier) -> QualifierLevels { q.levels(range) ?? .initial }
            fields = [
                ("Low", 1, { levels($0).low },
                 { q, v in
                     var l = levels(q)
                     l.low = min(v, l.high)
                     return .levels(range, .set(l))
                 }),
                ("High", 1, { levels($0).high },
                 { q, v in
                     var l = levels(q)
                     l.high = max(v, l.low)
                     return .levels(range, .set(l))
                 }),
                ("Soft", 1, { levels($0).softness },
                 { q, v in var l = levels(q); l.softness = v; return .levels(range, .set(l)) }),
            ]
        }
        var controls: [NSView] = []
        for field in fields {
            let caption = InspectorRowLabel(field.caption)
            caption.font = DS.sans(10)
            caption.setContentCompressionResistancePriority(.required, for: .horizontal)
            controls.append(caption)
            controls.append(
                OptionFieldControl(
                    width: 41, unit: range == .hue ? "°" : "", decimals: range == .hue ? 0 : 2,
                    min: 0, max: field.max,
                    read: { field.get(read()) },
                    write: { [weak binding] value in
                        binding?.apply(name, ops(field.put(read(), value)))
                    },
                    enabled: on,
                    onEdit: { [weak binding] in binding?.edited() }))
        }
        return inspectorRow(nil, controls, binding: binding, writes: ops(.reset))
    }
}

