        let domain = self.domain
        let spline = CurveTable.Spline(list, domain: domain)
        let path = NSBezierPath()
        for step in 0...steps {
            let x = domain.lower.x + Double(step) / Double(steps) * domain.span.x
            let at = screen(CurvePoint(x: x, y: spline.value(at: x)))
